(1108242, 135432, 6600, '<td valign="top">Composition works for me, suits the movie title, gray scale helped.  Good job.</td>', 'Composition works for me, suits the movie title, gray scale helped.  Good job.', '2005-01-14 21:26:01.000000', NULL, 1),
(1108244, 134394, 6600, '<td valign="top">Nice exposure and composition, fits into the movie theme nicely.  Low key effect nicely done.  Great job.</td>', 'Nice exposure and composition, fits into the movie theme nicely.  Low key effect nicely done.  Great job.', '2005-01-14 21:30:11.000000', NULL, 1),
